<?php
namespace App\Models;
use App\Enums\PageHelpAudience; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\BelongsToMany;
class PageHelp extends Model { use HasFactory; protected $fillable=['page_key','title','summary','content','audience','is_active','is_published','published_at','sort_order','created_by','updated_by']; protected function casts():array{return ['audience'=>PageHelpAudience::class,'is_active'=>'boolean','is_published'=>'boolean','published_at'=>'datetime','sort_order'=>'integer'];} public function roles():BelongsToMany{return $this->belongsToMany(Role::class);} public function permissions():BelongsToMany{return $this->belongsToMany(Permission::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function updater():BelongsTo{return $this->belongsTo(User::class,'updated_by');} public function scopePublished($q){return $q->where('is_active',true)->where('is_published',true)->where(fn($x)=>$x->whereNull('published_at')->orWhere('published_at','<=',now()));} }
